mapper.sql:
FROM fit_member_card mc
INNER JOIN fit_member m ON m.member_id = mc.member_id AND m.del_flag = '0'
LEFT JOIN fit_store st ON st.store_id = mc.store_id AND st.del_flag = '0'
LEFT JOIN fit_card_plan p ON p.plan_id = mc.plan_id AND p.del_flag = '0'
LEFT JOIN fit_coach coach ON coach.coach_id = mc.bind_coach_id AND coach.del_flag = '0'
LEFT JOIN fit_order o ON o.order_id = mc.order_id AND o.del_flag = '0'
WHERE mc.del_flag = '0'
AND mc.store_id = #{bo.storeId}
AND mc.member_id = #{bo.memberId}
AND mc.plan_id = #{bo.planId}
AND mc.bind_coach_id = #{bo.bindCoachId}
AND mc.order_id = #{bo.orderId}
AND mc.plan_type = #{bo.planType}
AND mc.card_status = #{bo.cardStatus}
AND mc.active_time >= #{bo.activeTimeStart}
AND mc.active_time <= #{bo.activeTimeEnd}
AND mc.expire_time >= #{bo.expireTimeStart}
AND mc.expire_time <= #{bo.expireTimeEnd}

    AND (mc.card_no LIKE CONCAT('%', #{bo.keyword}, '%')
        OR mc.card_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.real_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.nickname LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.mobile LIKE CONCAT('%', #{bo.keyword}, '%')
        OR o.order_no LIKE CONCAT('%', #{bo.keyword}, '%'))
